<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        @* ── Left Sidebar (Filters) ── *@
        <aside class="col-lg-3 mb-4">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    @* Categories *@
                    <h6>Category</h6>
                    @if (categories is not null)
                    {
                        @foreach (var cat in categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                       checked="@selectedCategories.Contains(cat)"
                                       @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                            </div>
                        }
                    }

                    <hr />

                    @* Price Range *@
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label form-label-sm">Min Price</label>
                        <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                               @bind="minPrice" placeholder="0" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label form-label-sm">Max Price</label>
                        <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                               @bind="maxPrice" placeholder="Any" />
                    </div>

                    <hr />

                    @* In Stock Toggle *@
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    @* Action Buttons *@
                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFilters" disabled="@isLoading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters" disabled="@isLoading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </aside>

        @* ── Main Content ── *@
        <main class="col-lg-9">
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (isLoading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary me-2" role="status"></div>
                    <span>Loading products…</span>
                </div>
            }
            else if (searchResult is null || searchResult.Items.Count == 0)
            {
                <div class="text-center py-5 text-muted">
                    <h4>No products found</h4>
                    <p>Try adjusting your filters or clearing them.</p>
                </div>
            }
            else
            {
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                    <div class="d-flex align-items-center gap-2">
                        <label class="form-label mb-0 text-nowrap">Sort by:</label>
                        <select class="form-select form-select-sm" style="width:auto"
                                value="@sortBy" @onchange="OnSortChanged">
                            <option value="price_asc">Price: Low to High</option>
                            <option value="price_desc">Price: High to Low</option>
                            <option value="name_asc">Name: A-Z</option>
                            <option value="rating_desc">Rating: Highest</option>
                        </select>
                    </div>
                    <span class="text-muted">
                        Showing @RangeStart–@RangeEnd of @searchResult.TotalCount products
                    </span>
                </div>

                @* Product Grid *@
                <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3 mb-4">
                    @foreach (var product in searchResult.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product"
                                         OnProductClicked="OnProductClicked"
                                         OnAddToCart="OnAddToCart" />
                        </div>
                    }
                </div>

                @* Pagination *@
                <nav aria-label="Product pagination">
                    <ul class="pagination justify-content-center flex-wrap">
                        <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
                            <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                    disabled="@(currentPage <= 1)">Previous</button>
                        </li>

                        @for (int i = 1; i <= TotalPages; i++)
                        {
                            var pageNum = i;
                            <li class="page-item @(pageNum == currentPage ? "active" : "")">
                                <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                            </li>
                        }

                        <li class="page-item @(currentPage >= TotalPages ? "disabled" : "")">
                            <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                    disabled="@(currentPage >= TotalPages)">Next</button>
                        </li>
                    </ul>
                </nav>
            }
        </main>
    </div>
</div>

@code {
    private List<string>? categories;
    private PagedResult<Product>? searchResult;

    // Filter state
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Paging / sorting state
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    // UI state
    private bool isLoading = true;
    private string? errorMessage;

    private int RangeStart => (searchResult!.Page - 1) * searchResult.PageSize + 1;
    private int RangeEnd => Math.Min(searchResult!.Page * searchResult.PageSize, searchResult.TotalCount);
    private int TotalPages => searchResult is null || searchResult.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)searchResult.TotalCount / searchResult.PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;
        StateHasChanged();

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            searchResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await LoadProducts();
    }

    private void OnProductClicked(Product product)
    {
        // Parent page handles navigation — for a top-level page we can use NavigationManager directly.
        // If this were a child component, the EventCallback would bubble up.
    }

    private void OnAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
    }
}
"}

